                            source: trackData.source || 'none',
                            language: selectedTrack.languageCode || '',
                            fetchedAt: nowFn(),
                            expiresAt,
                            staleReason,
                            fallbackReason: allowDomFallback ? 'panel-unavailable' : 'dom-disabled'
